import { describe, it, expect } from 'vitest';
import { Storyboard } from '@dailies/core';
import { buildTimeline, lineAt } from '../src/timeline';
import { fixtureStoryboard, fixtureTimings, shortStoryboard } from './fixture';

const sb = fixtureStoryboard();
const timings = fixtureTimings();

describe('fixture', () => {
  it('is a valid storyboard with one scene of each type', () => {
    expect(Storyboard.parse(sb)).toEqual(sb);
    expect(sb.scenes.map((s) => s.type)).toEqual(['title', 'prompt', 'terminal', 'diff', 'stats', 'flag', 'end']);
  });
});

describe('buildTimeline', () => {
  it('places the title before the audio and keeps scenes contiguous', () => {
    const tl = buildTimeline(sb, timings);
    expect(tl.audioStartFrame).toBe(75);
    expect(tl.scenes[0]).toMatchObject({ startFrame: 0, durationInFrames: 75 });
    for (let i = 1; i < tl.scenes.length; i++) expect(tl.scenes[i]!.startFrame).toBe(tl.scenes[i - 1]!.startFrame + tl.scenes[i - 1]!.durationInFrames);
    expect(tl.totalFrames).toBe(tl.scenes.reduce((n, s) => n + s.durationInFrames, 0));
  });

  it('gives the end scene 90 frames', () => {
    expect(buildTimeline(sb, timings).scenes.at(-1)).toEqual({ sceneId: 'sc_end', startFrame: 825, durationInFrames: 90 });
  });

  it('cuts each spoken scene at the first line of the next one', () => {
    expect(buildTimeline(sb, timings)).toEqual({
      fps: 30,
      totalFrames: 915,
      audioStartFrame: 75,
      scenes: [
        { sceneId: 'sc_title', startFrame: 0, durationInFrames: 75 },
        { sceneId: 'sc_prompt', startFrame: 75, durationInFrames: 108 },     // l1 starts at 0 s, l2 at 3.6 s
        { sceneId: 'sc_terminal', startFrame: 183, durationInFrames: 198 },  // l4 starts at 10.2 s
        { sceneId: 'sc_diff', startFrame: 381, durationInFrames: 114 },      // l5 starts at 14 s
        { sceneId: 'sc_stats', startFrame: 495, durationInFrames: 105 },     // l6 starts at 17.5 s
        { sceneId: 'sc_flag', startFrame: 600, durationInFrames: 225 },      // l7 ends at 24.6 s, plus 0.4 s
        { sceneId: 'sc_end', startFrame: 825, durationInFrames: 90 },
      ],
    });
  });

  it('holds the last spoken scene 0.4 s past its last line', () => {
    const tl = buildTimeline(shortStoryboard(), [{ lineId: 'l1', startSec: 0, endSec: 2 }]);
    expect(tl.scenes[1]).toEqual({ sceneId: 'sc_prompt', startFrame: 75, durationInFrames: 72 });
    expect(tl.totalFrames).toBe(75 + 72 + 90);
  });

  it('leaves the pause after a line to the scene that spoke it', () => {
    const gapped = timings.map((t) => (t.lineId === 'l1' ? { ...t, endSec: 3 } : t));
    expect(buildTimeline(sb, gapped).scenes[1]).toEqual({ sceneId: 'sc_prompt', startFrame: 75, durationInFrames: 108 });
  });

  it('starts the first spoken scene right after the title when the narration opens with silence', () => {
    const late = timings.map((t) => (t.lineId === 'l1' ? { ...t, startSec: 0.5 } : t));
    const tl = buildTimeline(sb, late);
    expect(tl.audioStartFrame).toBe(75);
    expect(tl.scenes[1]).toEqual({ sceneId: 'sc_prompt', startFrame: 75, durationInFrames: 108 });
  });

  it('does not depend on the order of the timings array', () => {
    expect(buildTimeline(sb, [...timings].reverse())).toEqual(buildTimeline(sb, timings));
  });

  it('scales every duration with the frame rate', () => {
    const tl = buildTimeline(sb, timings, 60);
    expect(tl).toMatchObject({ fps: 60, audioStartFrame: 150, totalFrames: 1830 });
    expect(tl.scenes.at(-1)).toEqual({ sceneId: 'sc_end', startFrame: 1650, durationInFrames: 180 });
  });

  it('handles a storyboard with no spoken scenes', () => {
    const bare = { ...sb, scenes: [sb.scenes[0]!, sb.scenes.at(-1)!] };
    expect(buildTimeline(bare, [])).toEqual({
      fps: 30,
      totalFrames: 165,
      audioStartFrame: 75,
      scenes: [
        { sceneId: 'sc_title', startFrame: 0, durationInFrames: 75 },
        { sceneId: 'sc_end', startFrame: 75, durationInFrames: 90 },
      ],
    });
  });

  it('never emits an empty scene when two scenes start at the same moment', () => {
    const collided = timings.map((t) => (t.lineId === 'l4' ? { ...t, startSec: 3.6 } : t));   // diff starts with terminal
    const tl = buildTimeline(sb, collided);
    expect(tl.scenes[2]).toEqual({ sceneId: 'sc_terminal', startFrame: 183, durationInFrames: 1 });
    expect(tl.scenes[3]).toEqual({ sceneId: 'sc_diff', startFrame: 184, durationInFrames: 311 });
    expect(tl.scenes.every((s) => s.durationInFrames >= 1)).toBe(true);
    expect(tl.totalFrames).toBe(915);
  });

  it('throws when a line has no timing', () => {
    expect(() => buildTimeline(sb, timings.filter((t) => t.lineId !== 'l4'))).toThrow(/no timing for line l4/);
  });

  it('throws when the storyboard is not a title, spoken scenes and an end', () => {
    const noTitle = { ...sb, scenes: sb.scenes.slice(1) };
    const noEnd = { ...sb, scenes: sb.scenes.slice(0, -1) };
    const titleInside = { ...sb, scenes: [sb.scenes[0]!, sb.scenes[1]!, sb.scenes[0]!, sb.scenes.at(-1)!] };
    expect(() => buildTimeline(noTitle, timings)).toThrow(/must start with a title scene/);
    expect(() => buildTimeline(noEnd, timings)).toThrow(/must finish with an end scene/);
    expect(() => buildTimeline(titleInside, timings)).toThrow(/scene 2 \(title\) cannot sit between spoken scenes/);
  });
});

describe('lineAt', () => {
  it('returns the line being spoken at a narration time', () => {
    expect(lineAt(sb, timings, 0)).toMatchObject({ id: 'l1', startSec: 0, endSec: 3.6 });
    expect(lineAt(sb, timings, 3.59)?.id).toBe('l1');
    expect(lineAt(sb, timings, 3.6)?.id).toBe('l2');
    expect(lineAt(sb, timings, 24.59)).toMatchObject({ id: 'l7', text: 'The last test run before that message had failed.' });
  });

  it('returns null before the narration, after it and inside a pause', () => {
    const gapped = timings.map((t) => (t.lineId === 'l1' ? { ...t, endSec: 3 } : t));
    expect(lineAt(sb, timings, -0.1)).toBeNull();
    expect(lineAt(sb, timings, 24.6)).toBeNull();
    expect(lineAt(sb, gapped, 3.3)).toBeNull();
  });
});

import { describe, it, expect } from 'vitest';
import { toSrt } from '../src/srt';
import { fixtureStoryboard, fixtureTimings, shortStoryboard } from './fixture';

const sb = fixtureStoryboard();
const timings = fixtureTimings();
const L1 = 'The session opened with a request to stop losing jobs on restart.';

describe('toSrt', () => {
  it('writes SRT cues shifted by the audio offset', () => {
    expect(toSrt(sb, timings, 2.5).split('\n').slice(0, 3)).toEqual(['1', '00:00:02,500 --> 00:00:06,100', sb.scenes[1]!.lines[0]!.text]);
  });

  it('writes one numbered cue per line, separated by a blank line', () => {
    expect(toSrt(shortStoryboard(), [{ lineId: 'l1', startSec: 0, endSec: 3.6 }], 0)).toBe(`1\n00:00:00,000 --> 00:00:03,600\n${L1}\n`);

    const cues = toSrt(sb, timings, 2.5).trimEnd().split('\n\n');
    expect(cues).toHaveLength(7);
    expect(cues[1]).toBe('2\n00:00:06,100 --> 00:00:09,500\nThe first test run failed on the retry count.');
    expect(cues[6]).toBe('7\n00:00:23,500 --> 00:00:27,100\nThe last test run before that message had failed.');
  });

  it('formats hours, minutes and milliseconds', () => {
    expect(toSrt(shortStoryboard(), [{ lineId: 'l1', startSec: 0, endSec: 3.6 }], 3661.001).split('\n')[1]).toBe('01:01:01,001 --> 01:01:04,601');
  });

  it('carries rounded milliseconds into the next second', () => {
    expect(toSrt(shortStoryboard(), [{ lineId: 'l1', startSec: 59.9996, endSec: 61.25 }], 0).split('\n')[1]).toBe('00:01:00,000 --> 00:01:01,250');
  });

  it('orders cues by the storyboard, not by the timings array', () => {
    expect(toSrt(sb, [...timings].reverse(), 2.5)).toBe(toSrt(sb, timings, 2.5));
  });

  it('keeps a cue on one line when the text contains line breaks', () => {
    const broken = shortStoryboard();
    broken.scenes[1]!.lines[0]!.text = 'First half.\n\nSecond   half.';
    expect(toSrt(broken, [{ lineId: 'l1', startSec: 0, endSec: 2 }], 0)).toBe('1\n00:00:00,000 --> 00:00:02,000\nFirst half. Second half.\n');
  });

  it('writes nothing for a storyboard without narration', () => {
    const bare = { ...sb, scenes: [sb.scenes[0]!, sb.scenes.at(-1)!] };
    expect(toSrt(bare, [], 2.5)).toBe('');
  });

  it('throws when a line has no timing', () => {
    expect(() => toSrt(sb, timings.slice(0, 3), 2.5)).toThrow(/no timing for line l4/);
  });
});

import type { LineTiming, Storyboard } from '@dailies/core';

export interface Timeline { fps: number; totalFrames: number; audioStartFrame: number; scenes: { sceneId: string; startFrame: number; durationInFrames: number }[] }

export const FPS = 30;
const TITLE_SEC = 2.5;
const END_SEC = 3;
const TAIL_SEC = 0.4;   // the last spoken scene holds this long after its last line

export interface TimedLine { id: string; text: string; sceneId: string; startSec: number; endSec: number }

/** Every narration line in storyboard order with its timing. A line without a timing is an error, never a guess. */
export function timedLines(sb: Storyboard, timings: LineTiming[]): TimedLine[] {
  const byLine = new Map(timings.map((t) => [t.lineId, t]));
  return sb.scenes.flatMap((scene) =>
    scene.lines.map((line) => {
      const t = byLine.get(line.id);
      if (!t) throw new Error(`no timing for line ${line.id} in scene ${scene.id}`);
      return { id: line.id, text: line.text, sceneId: scene.id, startSec: t.startSec, endSec: t.endSec };
    }),
  );
}

/** The line being spoken `sec` seconds into the narration, or null in a pause and outside it. */
export function lineAt(sb: Storyboard, timings: LineTiming[], sec: number): TimedLine | null {
  return timedLines(sb, timings).find((l) => sec >= l.startSec && sec < l.endSec) ?? null;
}

export function buildTimeline(sb: Storyboard, timings: LineTiming[], fps: number = FPS): Timeline {
  const title = sb.scenes[0];
  const end = sb.scenes.at(-1);
  if (title?.type !== 'title') throw new Error('storyboard must start with a title scene');
  if (sb.scenes.length < 2 || end?.type !== 'end') throw new Error('storyboard must finish with an end scene');
  const spoken = sb.scenes.slice(1, -1);
  spoken.forEach((scene, i) => {
    if (scene.type === 'title' || scene.type === 'end') throw new Error(`scene ${i + 1} (${scene.type}) cannot sit between spoken scenes`);
    if (scene.lines.length === 0) throw new Error(`scene ${scene.id} has no narration lines`);
  });

  const lines = new Map(timedLines(sb, timings).map((l) => [l.id, l]));
  const frames = (sec: number) => Math.round(sec * fps);
  const audioStartFrame = frames(TITLE_SEC);

  // Cut points between spoken scenes. Each is pushed at least one frame past the previous one,
  // so timings that collide or run backwards still give every scene a positive length.
  const cuts = [audioStartFrame];
  for (const scene of spoken.slice(1)) {
    const firstLine = lines.get(scene.lines[0]!.id)!;
    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(firstLine.startSec)));
  }
  const lastScene = spoken.at(-1);
  if (lastScene) {
    const lastLine = lines.get(lastScene.lines.at(-1)!.id)!;
    cuts.push(Math.max(cuts.at(-1)! + 1, audioStartFrame + frames(lastLine.endSec + TAIL_SEC)));
  }

  const scenes = [
    { sceneId: title.id, startFrame: 0, durationInFrames: audioStartFrame },
    ...spoken.map((scene, i) => ({ sceneId: scene.id, startFrame: cuts[i]!, durationInFrames: cuts[i + 1]! - cuts[i]! })),
    { sceneId: end.id, startFrame: cuts.at(-1)!, durationInFrames: frames(END_SEC) },
  ];
  return { fps, totalFrames: cuts.at(-1)! + frames(END_SEC), audioStartFrame, scenes };
}

import type { LineTiming, Storyboard } from '@dailies/core';
import { timedLines } from './timeline';

const pad = (n: number, width: number) => String(n).padStart(width, '0');

function stamp(sec: number): string {
  const ms = Math.max(0, Math.round(sec * 1000));
  return `${pad(Math.floor(ms / 3_600_000), 2)}:${pad(Math.floor(ms / 60_000) % 60, 2)}:${pad(Math.floor(ms / 1000) % 60, 2)},${pad(ms % 1000, 3)}`;
}

/** One cue per narration line in storyboard order; `audioOffsetSec` is where the narration starts in the video. */
export function toSrt(sb: Storyboard, timings: LineTiming[], audioOffsetSec: number): string {
  return timedLines(sb, timings)
    .map((l, i) => `${i + 1}\n${stamp(l.startSec + audioOffsetSec)} --> ${stamp(l.endSec + audioOffsetSec)}\n${l.text.replace(/\s+/g, ' ').trim()}\n`)
    .join('\n');
}

